  const now = new Date();
  const day0 = new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000);
  const day1 = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000);
  const day2 = new Date(now.getTime() - 1 * 24 * 60 * 60 * 1000);
